<?php
function inflow_controls_ready(){return process_ready()&&setting('inflow_controls_version','')==='5.2.1';}
function inflow_require_controls(){if(!inflow_controls_ready())throw new Exception('Run the latest Admin database upgrade before recording inflow.');}
function inflow_file_previous($hash,$exclude=0){$q=db()->prepare("SELECT id,batch_ref,status FROM inflow_batches WHERE file_hash=? AND id<>? AND status IN ('Confirmed','To Review') ORDER BY status='Confirmed' DESC,id LIMIT 1");$q->execute([$hash,$exclude]);return $q->fetch();}
function inflow_upload_check($file){inflow_require_controls();$hash=hash_file('sha256',$file['tmp_name']);$old=inflow_file_previous($hash);if($old)throw new Exception('This file is '.($old['status']==='Confirmed'?'Already Posted':'already awaiting review').': '.$old['batch_ref'].' (batch #'.$old['id'].'). Open the existing record; uploading again will not add stock.');return $hash;}
function inflow_record_hash($id,$path){if($path&&is_file(__DIR__.'/'.$path))db()->prepare('UPDATE inflow_batches SET file_hash=? WHERE id=?')->execute([hash_file('sha256',__DIR__.'/'.$path),$id]);}
function inflow_supplier($value){$value=trim((string)$value);if($value===''||strlen($value)>180)throw new Exception('Supplier / Source is required (up to 180 characters).');return $value;}
function inflow_claim_keys($b){$source=inflow_supplier($b['source_name']);$r=json_decode($b['result_json']??'[]',true)?:[];$refs=[];if($b['batch_type']==='Excel Upload')foreach($r['bulk_rows']??[] as $row)$refs[]=$row['reference'];else $refs[]=$b['reference_no'];$keys=[];foreach(array_unique($refs) as $ref){$ref=trim((string)$ref);if($ref===''||strlen($ref)>100)throw new Exception('Every supplier receipt requires a valid DR / Receipt Reference.');$keys[]=hash('sha256','supplier|'.norm($source).'|'.norm($ref));}return $keys;}
function inflow_duplicate_review($b,$claim=false){
 if(!inflow_controls_ready())return;
 if($b['batch_type']==='Manual')throw new Exception('Use the current Order Return review or Borrowed Items record for returns. Legacy manual drafts cannot bypass return validation.');
 if(!empty($b['file_hash'])){if($old=inflow_file_previous($b['file_hash'],$b['id']))throw new Exception('Already uploaded: '.$old['batch_ref'].' (batch #'.$old['id'].'). Cancel the duplicate draft.');}
 $keys=inflow_claim_keys($b);foreach($keys as $key){$q=db()->prepare('SELECT c.batch_id,b.batch_ref FROM inflow_receipt_claims c JOIN inflow_batches b ON b.id=c.batch_id WHERE c.claim_key=? AND c.active=1 AND c.batch_id<>?');$q->execute([$key,$b['id']]);if($old=$q->fetch())throw new Exception('Already Posted receipt: '.$old['batch_ref'].' (batch #'.$old['batch_id'].'). No stock will be added.');}
 // Legacy confirmed receipts did not reserve keys; compare their original references too.
 $q=db()->prepare("SELECT * FROM inflow_batches WHERE status='Confirmed' AND batch_type IN ('Receipt PDF','Excel Upload') AND id<>?");$q->execute([$b['id']]);foreach($q as $old){$meta=json_decode($old['result_json']??'[]',true)?:[];$oldRefs=$old['batch_type']==='Excel Upload'?array_column($meta['bulk_rows']??[],'reference'):[$old['reference_no']];$newRefs=$b['batch_type']==='Excel Upload'?array_column(json_decode($b['result_json'],true)['bulk_rows']??[],'reference'):[$b['reference_no']];$overlap=array_intersect(array_map('norm',$oldRefs),array_map('norm',$newRefs));if(!$overlap)continue;if(trim($old['source_name'])!==''&&norm($old['source_name'])===norm($b['source_name']))throw new Exception('Already Posted receipt reference: '.$old['batch_ref'].' (batch #'.$old['id'].').');if(trim($old['source_name'])==='')throw new Exception('Possible Duplicate: reference found in legacy batch #'.$old['id'].' without a supplier. Admin must identify the supplier in that history record before posting.');}
 if($claim)foreach($keys as $key)db()->prepare('INSERT INTO inflow_receipt_claims(claim_key,batch_id,active) VALUES(?,?,1)')->execute([$key,$b['id']]);
}
function inflow_supplier_update($id,$supplier){if(!can_action('correct_receipt_header'))throw new Exception('Permission required.');$supplier=inflow_supplier($supplier);$q=db()->prepare('SELECT * FROM inflow_batches WHERE id=?');$q->execute([$id]);$b=$q->fetch();if(!$b||!in_array($b['batch_type'],['Receipt PDF','Excel Upload'],true))throw new Exception('Supplier receipt not found.');if($b['status']==='Confirmed'&&current_user()['role']!=='Admin')throw new Exception('Admin must identify a historical receipt supplier.');if($b['status']==='Confirmed'&&trim((string)$b['source_name'])!==''&&norm($b['source_name'])!==norm($supplier))throw new Exception('Posted supplier identity cannot be changed. Request an approved correction instead.');if(in_array($b['status'],['Cancelled','Reversed'],true))throw new Exception('This receipt is closed.');db()->prepare('UPDATE inflow_batches SET source_name=? WHERE id=?')->execute([$supplier,$id]);audit('Identify inflow supplier','Inflow Batch',$b['batch_ref'],$b['source_name'].' → '.$supplier);}
function inflow_supplier_form($id){$q=db()->prepare("SELECT * FROM inflow_batches WHERE id=? AND batch_type IN ('Receipt PDF','Excel Upload')");$q->execute([$id]);if(!($b=$q->fetch())||!can_action('correct_receipt_header'))return;echo '<div class="card"><h3>Supplier / Source</h3><form method="post" action="actions.php" class="inline-form"><input type="hidden" name="action" value="inflow_supplier"><input type="hidden" name="batch_id" value="'.$id.'"><input type="hidden" name="return" value="'.($b['batch_type']==='Receipt PDF'?'receipt_review':'inflow_batch').'&id='.$id.'"><label>Supplier / Source<input name="supplier" value="'.e($b['source_name']).'" maxlength="180" required></label><button class="btn secondary">Save Supplier</button></form></div>';}
